declare(strict_types=1);

namespace Iranimij\OpenImport\Model\Import\UrlRewrite;

use Iranimij\OpenImport\Api\Data\ProfileInterface;
use Iranimij\OpenImport\Model\Export\EntitySourceInterface;

/**
 * URL rewrite export: one row per rewrite with the store view code and the entity it belongs to as a SKU,
 * category path or CMS page identifier. The file imports back as it is (Magento's generated URLs included, marked
 * with autogenerated = 1).
 */
class UrlRewriteEntitySource implements EntitySourceInterface
{
    /**
     * @param UrlRewriteRecords $records
     */
    public function __construct(private readonly UrlRewriteRecords $records)
    {
    }

    /**
     * @inheritDoc
     */
    public function read(ProfileInterface $profile, callable $onHeader, callable $onRow): void
    {
        $onHeader(UrlRewriteImporter::COLUMNS);
        foreach ($this->records->all() as $rewrite) {
            $onRow($this->row($rewrite));
        }
    }

    /**
     * @inheritDoc
     */
    public function finish(ProfileInterface $profile, int $runId): void
    {
    }

    /**
     * @inheritDoc
     */
    public function columns(string $entity): array
    {
        return UrlRewriteImporter::COLUMNS;
    }

    /**
     * A url_rewrite row as a file row.
     *
     * @param array<string, mixed> $rewrite
     * @return array<string, string>
     */
    public function row(array $rewrite): array
    {
        $type = (string) $rewrite['entity_type'];
        $id = (int) $rewrite['entity_id'];

        return [
            'request_path' => (string) $rewrite['request_path'],
            'store_code' => $this->records->storeCode((int) $rewrite['store_id']),
            'target_path' => (string) ($rewrite['target_path'] ?? ''),
            'redirect_type' => (string) (int) $rewrite['redirect_type'],
            'entity_type' => $type,
            'product_sku' => $type === UrlRewriteRecords::PRODUCT ? (string) ($this->records->sku($id) ?? '') : '',
            'category_path' => $type === UrlRewriteRecords::CATEGORY
                ? (string) ($this->records->categoryPath($id) ?? '') : '',
            'cms_page' => $type === UrlRewriteRecords::CMS_PAGE
                ? (string) ($this->records->cmsPageIdentifier($id) ?? '') : '',
            'description' => (string) ($rewrite['description'] ?? ''),
            'autogenerated' => (string) (int) $rewrite['is_autogenerated'],
            'metadata' => (string) ($rewrite['metadata'] ?? ''),
        ];
    }
}
